import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,ag as n}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse(`{"title":"Gemini Tasks","description":"Google's free personal agent in the Gemini app (2026-11-17): Chat→Task switch, phone calls to US businesses, Google Pay checkout via AP2, SMS and email task intake — and where it stands against ChatGPT Work, Claude computer use, and Grok Bot.","frontmatter":{"title":"Gemini Tasks","description":"Google's free personal agent in the Gemini app (2026-11-17): Chat→Task switch, phone calls to US businesses, Google Pay checkout via AP2, SMS and email task intake — and where it stands against ChatGPT Work, Claude computer use, and Grok Bot.","domain":"product","tags":["agent"],"role":"tutorial"},"headers":[],"relativePath":"products/gemini/gemini-tasks.md","filePath":"products/gemini/gemini-tasks.md","lastUpdated":1795792629000}`),s={name:"products/gemini/gemini-tasks.md"};function i(r,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="gemini-tasks" tabindex="-1">Gemini Tasks <a class="header-anchor" href="#gemini-tasks" aria-label="Permalink to &quot;Gemini Tasks&quot;">​</a></h1><blockquote><p>Google&#39;s personal agent inside the Gemini app, launched 2026-11-17. Switch the home-screen toggle from Chat to Task and Gemini runs multi-step tasks in the background, then notifies you. Runs on Gemini 4 Hydrogen.</p><p>Sources (first-hand, read in full 2026-11-27): <a href="https://blog.google/innovation-and-ai/products/gemini-app/tasks-in-gemini-free-new-features/" target="_blank" rel="noreferrer">official announcement</a>, <a href="https://gemini.google/gp/release-notes/?hl=en" target="_blank" rel="noreferrer">release notes 2026.11.17</a>, <a href="https://support.google.com/gemini/answer/17094507" target="_blank" rel="noreferrer">help center</a>, <a href="https://support.google.com/gemini/answer/18961634?hl=en-301" target="_blank" rel="noreferrer">phone-calls help</a>. Community reactions were collected from X via grok CLI on 2026-11-27; no route in our fleet could do a live hands-on test, so nothing here claims first-hand use.</p></blockquote><h2 id="what-it-is-—-and-is-not" tabindex="-1">What it is — and is not <a class="header-anchor" href="#what-it-is-—-and-is-not" aria-label="Permalink to &quot;What it is — and is not&quot;">​</a></h2><ul><li><strong>Free in six countries</strong>: US, Japan, Korea, Canada, Australia, India. Outside the six, a Google AI Pro or Ultra subscription is required; the EEA, Nigeria, Switzerland, and the UK cannot use it at all, even subscribed.</li><li><strong>Not in mainland China</strong>: no official timeline has been published.</li><li><strong>Predecessor</strong>: Spark, in beta for subscribers since May 2026, renamed Task.</li><li><strong>Limits</strong>: 18+, personal Google account (work/school accounts not supported), History on; at most 15 tasks running at once; daily caps on phone calls (exact number unpublished); still experimental — Google says tasks can fail or miss the mark.</li></ul><h2 id="what-it-can-do" tabindex="-1">What it can do <a class="header-anchor" href="#what-it-can-do" aria-label="Permalink to &quot;What it can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>How it works</th><th>Scope</th></tr></thead><tbody><tr><td>Call US businesses</td><td>Calls several at once, waits on hold, books by your Calendar availability; discloses it is AI, merchants can opt out; no 911, no payments or sensitive info on the call</td><td>US only; Louisiana, Indiana, Minnesota, Montana excluded; Nebraska limited Sun/holidays 13:00–21:00</td></tr><tr><td>Shop with Google Pay</td><td>Sets a product + price cap, stages checkout with an itemised summary, buys only after your 1-tap + device approval, via a one-time virtual card; uses the Agent Payments Protocol (AP2)</td><td>US only, English, 18+, personal account; Mastercard/Visa live, Amex coming soon</td></tr><tr><td>Text intake</td><td>SMS/RCS via Google Messages or iMessage; mid-task steering by reply</td><td>US only; verified US number, eligible carrier</td></tr><tr><td>Email intake</td><td>Forward mail to <a href="mailto:gemini@google.com" target="_blank" rel="noreferrer">gemini@google.com</a>; replies 1:1 only, never Reply-All</td><td>US only; Gmail/Apple Mail/Outlook</td></tr><tr><td>Cross-app + files</td><td>60+ connected apps (Gmail, Calendar, Drive, Docs, Sheets, Wallet, Maps, YouTube…); generates docs, sheets, decks, code, web pages; scheduled routines</td><td>Six free countries</td></tr></tbody></table><p>UCP (Universal Commerce Protocol) integration is &quot;up next&quot; — <strong>not</strong> live at launch. Tasks run in Google Cloud&#39;s Agent Compute Engine: a hardware-isolated VM per account, plus prompt-injection filters and Safe Browsing. The help center warns explicitly that these defences <strong>cannot guarantee</strong> prompt-injection risks away; sensitive tasks should not be scheduled, and login/payment details must never be typed into a task thread.</p><h2 id="how-it-compares" tabindex="-1">How it compares <a class="header-anchor" href="#how-it-compares" aria-label="Permalink to &quot;How it compares&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Gemini Tasks</th><th>ChatGPT Work</th><th>Claude computer use</th><th>Grok Bot</th></tr></thead><tbody><tr><td>Price</td><td>Free in six countries</td><td>Subscription (Plus ~$20/mo)</td><td>API token pricing</td><td>Inside X subscriptions</td></tr><tr><td>Native phone calls</td><td>Yes — parallel calls, hold music, transcript</td><td>No native calls</td><td>No native calls (devs wire Twilio etc.)</td><td>No native calls reported</td></tr><tr><td>Native shopping</td><td>Yes — Google Pay + AP2 + spending cap + pre-purchase approval</td><td>Cloud-browser shopping; ChatGPT Wallet added 2026-11-13 (tokenised card, biometric approval each purchase)</td><td>No native shopping; computer use can operate stores or APIs</td><td>No native shopping loop reported</td></tr><tr><td>Openness</td><td>Devs apply to the Connected Apps Platform; no equivalent of MCP/API agent framework published</td><td>Plugins, Actions, 1,400+ plugins; Work shares limits with Codex</td><td>MCP + API path is the most explicit of the four</td><td>Connectors/MCP on a persistent cloud computer</td></tr><tr><td>Shape</td><td>Personal-life tasks: bookings, bills, shopping, family schedules</td><td>Longer knowledge-work outcomes (briefs, decks, sheets)</td><td>Desktop-grade generic operation + dev workflows</td><td>Named persistent teammate on a shared cloud computer</td></tr></tbody></table><p><strong>Takeaway: Gemini Tasks differentiates on &quot;free + real phone calls + payments loop&quot;. Its weak side is openness</strong> — Claude and ChatGPT publish clearer developer paths (API, MCP, plugins), while Gemini only offers Connected Apps Platform applications so far. ChatGPT and Claude have no native &quot;call and wait on hold&quot; or AP2 payments loop.</p><p>Notes on lineage (verified 2026-11-27 against public sources): ChatGPT Atlas was a real product — an OpenAI browser launched 2025-10-21, retired 2026-08-09, folded into the ChatGPT desktop app; its agent capability now lives in ChatGPT Work (launched 2026-07-09). Operator (2025-01-23) was retired 2025-08-31 and folded into ChatGPT agent mode. See <a href="./../codex/chatgpt-work.html">ChatGPT Work</a> and <a href="./../grok/grok-bot.html">Grok Bot</a>.</p><h2 id="community-reality-check-10-days-in-2026-11-27" tabindex="-1">Community reality check, 10 days in (2026-11-27) <a class="header-anchor" href="#community-reality-check-10-days-in-2026-11-27" aria-label="Permalink to &quot;Community reality check, 10 days in (2026-11-27)&quot;">​</a></h2><ul><li><strong>Only screenshot-backed success found</strong>: a call to Trader Joe&#39;s (Redmond) confirming butternut squash in stock, 2026-11-22 (<a href="https://agihunt.info/en/p/1a20472bd22261343a13a4495f2" target="_blank" rel="noreferrer">AGI Hunt</a>). A pet-grooming booking reached voicemail on the second attempt after the first failed (<a href="https://edtimes.in/ai-can-now-make-calls-and-buy-things-for-you-will-you-let-it/" target="_blank" rel="noreferrer">ED Times, via r/GeminiAI</a>).</li><li><strong>Failures reported on X</strong> (grok search summaries, not individually re-opened): tasks stalling mid-way until nudged; a paying Pro + Workspace user cut off overnight (ticket #77990451, unrecovered); refusal to connect to a private P2P chat app while OpenAI Dots, Grok Bot, Muse, and Nous Hermes connected; uncontrollable reasoning depth.</li><li><strong>Geography dominates complaints</strong>: UK/German/EU users asking for an ETA; no mainland-China complaints found.</li><li><strong>Zero found</strong>: shopping-checkout success stories, email/SMS intake walkthroughs, restaurant/hotel booking successes.</li><li><strong>Name collision</strong>: the product shares its name with Google Tasks, the 2018 to-do app — journalist Joanna Stern asked about it publicly on 2026-11-18; Google has not responded.</li></ul><h2 id="open-questions-not-facts" tabindex="-1">Open questions (not facts) <a class="header-anchor" href="#open-questions-not-facts" aria-label="Permalink to &quot;Open questions (not facts)&quot;">​</a></h2><p>Email/SMS channel fine print; language coverage in the six free countries; Windows-app support; Pro/Ultra prices and quotas; the Nebraska blog-footnote wording (help center says limited hours, some secondary reports say fully excluded); any &quot;Gemini Bots&quot; rumour (unconfirmed, non-official logo — do not cite as fact).</p><p><em>Companion tutorial (Chinese, X Article draft, awaiting human publish authorisation): <code>content-home/workflows/x-article-operations/projects/x-article-2026-11-27-gemini-tasks/</code>.</em></p>',16)])])}const f=t(s,[["render",i]]);export{k as __pageData,f as default};
